INSERT INTO metadata.cim_ref_attributes (class_name, name, is_association, range, multiplicity, description, source) VALUES
  ('ACDCConverter', 'ACDCConverterDCTerminal', true, 'ACDCConverter', NULL, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'baseS', true, 'ApparentPower', NULL, 'Base apparent power of the converter pole.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'idc', true, 'CurrentFlow', NULL, 'Converter DC current, also called Id. Converter state variable, result from power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'idleLoss', true, 'ActivePower', NULL, 'Active power loss in pole at no power transfer. Converter configuration data used in power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'maxUdc', true, 'Voltage', NULL, 'The maximum voltage on the DC side at which the converter should operate. Converter configuration data used in power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'minUdc', true, 'Voltage', NULL, 'Min allowed converter DC voltage. Converter configuration data used in power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'numberOfValves', false, 'nonNegativeInteger', NULL, 'Number of valves in the converter. Used in loss calculations.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'p', true, 'ActivePower', NULL, 'Active power at the point of common coupling. Load sign convention is used, i.e. positive sign means flow out from a node. Starting value for a steady state solution in the case a simplified power flow model is used.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'poleLossP', true, 'ActivePower', NULL, 'The active power loss at a DC Pole = idleLoss + switchingLoss*|Idc| + resitiveLoss*Idc^2 For lossless operation Pdc=Pac For rectifier operation with losses Pdc=Pac-lossP For inverter operation with losses Pdc=Pac+lossP Converter state variable used in power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'q', true, 'ReactivePower', NULL, 'Reactive power at the point of common coupling. Load sign convention is used, i.e. positive sign means flow out from a node. Starting value for a steady state solution in the case a simplified power flow model is used.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'ratedUdc', true, 'Voltage', NULL, 'Rated converter DC voltage, also called UdN. Converter configuration data used in power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'resistiveLoss', true, 'Resistance', NULL, 'Converter configuration data used in power flow. Refer to poleLossP.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'switchingLoss', true, 'ActivePowerPerCurrentFlow', NULL, 'Switching losses, relative to the base apparent power ''baseS''. Refer to poleLossP.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'targetPpcc', true, 'ActivePower', NULL, 'Real power injection target in AC grid, at point of common coupling.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'targetUdc', true, 'Voltage', NULL, 'Target value for DC voltage magnitude.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'uc', true, 'Voltage', NULL, 'Line-to-line converter voltage, the voltage at the AC side of the valve. Converter state variable, result from power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'udc', true, 'Voltage', NULL, 'Converter voltage at the DC side, also called Ud. Converter state variable, result from power flow.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverter', 'valveU0', true, 'Voltage', NULL, 'Valve threshold voltage, also called Uvalve. Forward voltage drop when the valve is conducting. Used in loss calculations, i.e. the switchLoss depend on numberOfValves * valveU0.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCConverterDCTerminal', 'polarity', true, 'DCPolarityKind', NULL, 'Represents the normal network polarity condition.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCTerminal', 'BusNameMarker', true, 'ACDCTerminal', NULL, 'The bus name marker used to name the bus (topological node).The terminals associated with this bus name marker.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCTerminal', 'Measure', true, 'ACDCTerminal', NULL, 'Measurements associated with this terminal defining where the measurement is placed in the network topology. It may be used, for instance, to capture the sensor position, such as a voltage transformer (PT) at a busbar or a current transformer (CT) at the bar between a breaker and an isolator.One or more measurements may be associated with a terminal in the network.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCTerminal', 'OperationalLimitSet', true, 'ACDCTerminal', NULL, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('ACDCTerminal', 'connected', false, 'boolean', NULL, 'The connected status is related to a bus-branch model and the topological node to terminal relation. True implies the terminal is connected to the related topological node and false implies it is not. In a bus-branch model, the connected status is used to tell if equipment is disconnected without having to change the connectivity described by the topological node to terminal relation. A valid case is that conducting equipment can be connected in one end and open in the other. In particular for an AC line segment, where the reactive line charging can be significant, this is a relevant case.', 'schema/cim/IEC_CIM.ttl'),
  ('ACDCTerminal', 'sequenceNumber', false, 'nonNegativeInteger', NULL, 'The orientation of the terminal connections for a multiple terminal conducting equipment. The sequence numbering starts with 1 and additional terminals should follow in increasing order. The first terminal is the "starting point" for a two terminal branch.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'ACLineSegmentPhase', true, 'ACLineSegment', NULL, 'The line segment phases which belong to the line segment.The line segment to which the phase belongs.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'Cut', true, 'ACLineSegment', NULL, 'Cuts applied to the line segment.The line segment to which the cut is applied.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'GroundAction', true, 'ACLineSegment', NULL, 'Ground action involving clamp usage (for the case when the ground is applied along the line segment instead of at its terminals).The line segment that this ground action will affect. This is the only way to access relationship to clamp in case the ground needs to be placed along the line segment.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'JumperAction', true, 'ACLineSegment', NULL, 'Jumper action involving clamp usage (for the case when the jumper is applied along the line segment instead of at its terminals).The line segment that this jumper action will affect. This is the only way to access relationship to clamp in case the jumper needs to connect along the line segment.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'LineFault', true, 'ACLineSegment', NULL, 'The line faults of the line segment.The line segment of this line fault.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'PerLengthImpedance', true, 'ACLineSegment', NULL, 'Per-length impedance of this line segment.All line segments described by this per-length impedance.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'WireSpacing', true, 'ACLineSegment', NULL, 'Wire spacing configuration for this line segment.All line segments described with this wire spacing configuration.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'b0ch', true, 'Susceptance', NULL, 'Zero sequence shunt (charging) susceptance, uniformly distributed, of the entire line section.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'bch', true, 'Susceptance', NULL, 'Positive sequence shunt (charging) susceptance, uniformly distributed, of the entire line section. This value represents the full charging over the full length of the line.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'g0ch', true, 'Conductance', NULL, 'Zero sequence shunt (charging) conductance, uniformly distributed, of the entire line section.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'gch', true, 'Conductance', NULL, 'Positive sequence shunt (charging) conductance, uniformly distributed, of the entire line section.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'r', true, 'Resistance', NULL, 'Positive sequence series resistance of the entire line section.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'r0', true, 'Resistance', NULL, 'Zero sequence series resistance of the entire line section.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'shortCircuitEndTemperature', true, 'Temperature', NULL, 'Maximum permitted temperature at the end of SC for the calculation of minimum short-circuit currents. Used for short circuit data exchange according to IEC 60909', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'x', true, 'Reactance', NULL, 'Positive sequence series reactance of the entire line section.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegment', 'x0', true, 'Reactance', NULL, 'Zero sequence series reactance of the entire line section.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegmentPhase', 'phase', true, 'SinglePhaseKind', NULL, 'The phase connection of the wire at both ends.', 'schema/cim/IEC_CIM.ttl'),
  ('ACLineSegmentPhase', 'sequenceNumber', false, 'nonNegativeInteger', NULL, 'Number designation for this line segment phase. Each line segment phase within a line segment should have a unique sequence number. This is useful for unbalanced modeling to bind the mathematical model (PhaseImpedanceData of PerLengthPhaseImpedance) with the connectivity model (this class) and the physical model (WirePosition) without tight coupling.', 'schema/cim/IEC_CIM.ttl'),
  ('ASRequirements', 'intervalStartTime', false, 'dateTime', NULL, 'The start of the time interval for which requirement is defined.', 'schema/cim/IEC_CIM.ttl'),
  ('AcceptanceTest', 'dateTime', false, 'dateTime', NULL, 'Date and time the asset was last tested using the ''type'' of test and yielding the current status in ''success'' attribute.', 'schema/cim/IEC_CIM.ttl'),
  ('AcceptanceTest', 'success', false, 'boolean', NULL, 'True if asset has passed acceptance test and may be placed in or is in service. It is set to false if asset is removed from service and is required to be tested again before being placed back in service, possibly in a new location. Since asset may go through multiple tests during its lifecycle, the date of each acceptance test may be recorded in ''Asset.ActivityRecord.status.dateTime''.', 'schema/cim/IEC_CIM.ttl'),
  ('AcceptanceTest', 'type', false, 'string', NULL, 'Type of test or group of tests that was conducted on ''dateTime''.', 'schema/cim/IEC_CIM.ttl'),
  ('AccessPermit', 'applicationNumber', false, 'string', NULL, 'Permit application number that is used by municipality, state, province, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('AccessPermit', 'effectiveDate', false, 'date', NULL, 'Date that permit became official.', 'schema/cim/IEC_CIM.ttl'),
  ('AccessPermit', 'expirationDate', false, 'date', NULL, 'Permit expiration date.', 'schema/cim/IEC_CIM.ttl'),
  ('AccessPermit', 'payment', true, 'Money', NULL, 'Total cost of permit.', 'schema/cim/IEC_CIM.ttl'),
  ('AccessPermit', 'permitID', false, 'string', NULL, 'Permit identifier.', 'schema/cim/IEC_CIM.ttl'),
  ('AccountMovement', 'amount', true, 'Money', NULL, 'Amount that was credited to/debited from an account. For example: payment received/interest charge on arrears.', 'schema/cim/IEC_CIM.ttl'),
  ('AccountMovement', 'dateTime', false, 'dateTime', NULL, 'Date and time when the credit/debit transaction was performed.', 'schema/cim/IEC_CIM.ttl'),
