  ('ActivityRecord', 'Author', true, 'ActivityRecord', NULL, 'Author of this activity record.All activity records with this author.', 'schema/cim/IEC_CIM.ttl'),
  ('ActivityRecord', 'createdDateTime', false, 'dateTime', NULL, 'Date and time this activity record has been created (different from the ''status.dateTime'', which is the time of a status change of the associated object, if applicable).', 'schema/cim/IEC_CIM.ttl'),
