  ('DotInstruction', 'economicMaxOverride', false, 'float', NULL, 'Economic Max Limit override for unit, this value is null, if it is not, this value overrides the Energy column value. Allows dispatcher to override the unit''s energy value.', 'schema/cim/IEC_CIM.ttl'),
  ('DotInstruction', 'expectedEnergy', false, 'float', NULL, 'Expected energy.', 'schema/cim/IEC_CIM.ttl'),
  ('DotInstruction', 'generatorPerformanceDegree', false, 'float', NULL, 'The Degree of Generator Performance (DGP) used for the unit. Measure of how a generator responds to raise /lower signals. Calculated every five minutes.', 'schema/cim/IEC_CIM.ttl'),
  ('DotInstruction', 'hourAheadSchedEnergy', false, 'float', NULL, 'HASP results.', 'schema/cim/IEC_CIM.ttl'),
  ('DotInstruction', 'hourlySchedule', false, 'float', NULL, 'Hourly Schedule (DA Energy Schedule).', 'schema/cim/IEC_CIM.ttl'),
