  ('EndDeviceControlType', 'EndDeviceControl', true, 'EndDeviceControlType', NULL, 'All end device controls of this type.Type of this end device control.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceControlType', 'domain', false, 'string', NULL, 'High-level nature of the control.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceControlType', 'eventOrAction', false, 'string', NULL, 'The most specific part of this control type. It is mainly in the form of a verb that gives action to the control that just occurred.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceControlType', 'subDomain', false, 'string', NULL, 'More specific nature of the control, as a further sub-categorisation of ''domain''.', 'schema/cim/IEC_CIM.ttl'),
  ('EndDeviceControlType', 'type', false, 'string', NULL, 'Type of physical device from which the control was created. A value of zero (0) can be used when the source is unknown.', 'schema/cim/IEC_CIM.ttl'),
