  ('GovCT1', 'tc', true, 'Seconds', NULL, 'Turbine lead time constant (Tc). Typical Value = 0.', 'schema/cim/IEC_CIM.ttl'),
  ('GovCT1', 'tdgov', true, 'Seconds', NULL, 'Governor derivative controller time constant (Tdgov). Typical Value = 1.', 'schema/cim/IEC_CIM.ttl'),
  ('GovCT1', 'teng', true, 'Seconds', NULL, 'Transport time delay for diesel engine used in representing diesel engines where there is a small but measurable transport delay between a change in fuel flow setting and the development of torque (Teng). Teng should be zero in all but special cases where this transport delay is of particular concern. Typical Value = 0.', 'schema/cim/IEC_CIM.ttl'),
  ('GovCT1', 'tfload', true, 'Seconds', NULL, 'Load Limiter time constant (Tfload) (&gt;0). Typical Value = 3.', 'schema/cim/IEC_CIM.ttl'),
