  ('GovCT2', 'wfnl', true, 'PU', NULL, 'No load fuel flow (Wfnl). Typical Value = 0.187.', 'schema/cim/IEC_CIM.ttl'),
  ('GovCT2', 'wfspd', false, 'boolean', NULL, 'Switch for fuel source characteristic to recognize that fuel flow, for a given fuel valve stroke, can be proportional to engine speed (Wfspd). true = fuel flow proportional to speed (for some gas turbines and diesel engines with positive displacement fuel injectors) false = fuel control system keeps fuel flow independent of engine speed. Typical Value = false.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 'at', true, 'PU', NULL, 'Ambient temperature load limit (Load Limit). Typical Value = 1.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 'dturb', true, 'PU', NULL, 'Turbine damping factor (Dturb). Typical Value = 0.18.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 'kt', true, 'PU', NULL, 'Temperature limiter gain (Kt). Typical Value = 3.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 'mwbase', true, 'ActivePower', NULL, 'Base for power values (MWbase) (&gt; 0).', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 'r', true, 'PU', NULL, 'Permanent droop (R). Typical Value = 0.04.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 't1', true, 'Seconds', NULL, 'Governor mechanism time constant (T1). T1 represents the natural valve positioning time constant of the governor for small disturbances, as seen when rate limiting is not in effect. Typical Value = 0.5.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 't2', true, 'Seconds', NULL, 'Turbine power time constant (T2). T2 represents delay due to internal energy storage of the gas turbine engine. T2 can be used to give a rough approximation to the delay associated with acceleration of the compressor spool of a multi-shaft engine, or with the compressibility of gas in the plenum of a the free power turbine of an aero-derivative unit, for example. Typical Value = 0.5.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 't3', true, 'Seconds', NULL, 'Turbine exhaust temperature time constant (T3). Typical Value = 3.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 'vmax', true, 'PU', NULL, 'Maximum turbine power, PU of MWbase (Vmax). Typical Value = 1.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST', 'vmin', true, 'PU', NULL, 'Minimum turbine power, PU of MWbase (Vmin). Typical Value = 0.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST1', 'a', false, 'float', NULL, 'Turbine power time constant numerator scale factor (a). Typical Value = 0.8.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST1', 'b', false, 'float', NULL, 'Turbine power time constant denominator scale factor (b). Typical Value = 1.', 'schema/cim/IEC_CIM.ttl'),
