  ('GovGAST1', 'db2', true, 'ActivePower', NULL, 'Unintentional dead-band (db2). Unit = MW. Typical Value = 0.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST1', 'eps', true, 'Frequency', NULL, 'Intentional db hysteresis (eps). Unit = Hz. Typical Value = 0.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST1', 'fidle', true, 'PU', NULL, 'Fuel flow at zero power output (Fidle). Typical Value = 0.18.', 'schema/cim/IEC_CIM.ttl'),
  ('GovGAST1', 'gv1', true, 'PU', NULL, 'Nonlinear gain point 1, PU gv (Gv1). Typical Value = 0.', 'schema/cim/IEC_CIM.ttl'),
