  ('PackageDependenciesCIMVersion', 'date', false, 'date', NULL, 'Date of last change to the main package dependencies in format YYYY-MM-DD. This is updated when the version attribute is updated.', 'schema/cim/IEC_CIM.ttl'),
  ('PackageDependenciesCIMVersion', 'version', false, 'string', NULL, 'The version of the main subpackages of the combined CIM model. The format is simply an integer. The version (and date) initial values should be updated any time the dependencies in the model change and require an actual change to the diagrams within this package.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'appliance', true, 'ControlledAppliance', NULL, 'Appliance being controlled.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'avgLoadAdjustment', true, 'PerCent', NULL, 'Used to define a maximum energy usage limit as a percentage of the client implementations specific average energy usage. The load adjustment percentage is added to 100% creating a percentage limit applied to the client implementations specific average energy usage. A -10% load adjustment percentage will establish an energy usage limit equal to 90% of the client implementations specific average energy usage. Each load adjustment percentage is referenced to the client implementations specific average energy usage. There are no cumulative effects. The range of this field is -100% to +100% with a resolution of 1. A -100% value equals a total load shed. A +100% value will limit the energy usage to the client implementations specific average energy usage.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'cancelControlMode', false, 'string', NULL, 'Encoding of cancel control.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'cancelDateTime', false, 'dateTime', NULL, 'Timestamp when a canceling of the event is scheduled to start.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'cancelNow', false, 'boolean', NULL, 'If true, a canceling of the event should start immediately.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'coolingOffset', true, 'Temperature', NULL, 'Requested offset to apply to the normal cooling setpoint at the time of the start of the event. It represents a temperature change that will be applied to the associated cooling set point. The temperature offsets will be calculated per the local temperature in the thermostat. The calculated temperature will be interpreted as the number of degrees to be added to the cooling set point. Sequential demand response events are not cumulative. The offset shall be applied to the normal setpoint.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'coolingSetpoint', true, 'Temperature', NULL, 'Requested cooling set point. Temperature set point is typically defined and calculated based on local temperature.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'criticalityLevel', false, 'string', NULL, 'Level of criticality for the action of this control. The action taken by load control devices for an event can be solely based on this value, or in combination with other load control event fields supported by the device.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'dutyCycle', true, 'PerCent', NULL, 'Maximum "on" state duty cycle as a percentage of time. For example, if the value is 80, the device would be in an "on" state for 80% of the time for the duration of the action.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'enrollmentGroup', false, 'string', NULL, 'Provides a mechanism to direct load control actions to groups of PAN devices. It can be used in conjunction with the PAN device types.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'heatingOffset', true, 'Temperature', NULL, 'Requested offset to apply to the normal heating setpoint at the time of the start of the event. It represents a temperature change that will be applied to the associated heating set point. The temperature offsets will be calculated per the local temperature in the thermostat. The calculated temperature will be interpreted as the number of degrees to be subtracted from the heating set point. Sequential demand response events are not cumulative. The offset shall be applied to the normal setpoint.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDemandResponse', 'heatingSetpoint', true, 'Temperature', NULL, 'Requested heating set point. Temperature set point is typically defined and calculated based on local temperature.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDisplay', 'confirmationRequired', false, 'boolean', NULL, 'If true, the requesting entity (e.g. retail electric provider) requires confirmation of the successful display of the text message.', 'schema/cim/IEC_CIM.ttl'),
