  ('PanDisplay', 'textMessage', false, 'string', NULL, 'Text to be displayed by a PAN device.', 'schema/cim/IEC_CIM.ttl'),
  ('PanDisplay', 'transmissionMode', true, 'TransmissionModeKind', NULL, 'Transmission mode to be used for this PAN display control.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricing', 'providerID', false, 'nonNegativeInteger', NULL, 'Unique identifier for the commodity provider.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricingDetail', 'PanPricing', true, 'PanPricingDetail', NULL, 'PAN pricing command/action issuing this price detail.All pricing details issued by this PAN pricing command/action.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricingDetail', 'alternateCostDelivered', false, 'float', NULL, 'Alternative measure of the cost of the energy consumed. An example might be the emissions of CO2 for each kWh of electricity consumed providing a measure of the environmental cost.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricingDetail', 'alternateCostUnit', false, 'string', NULL, 'Cost unit for the alternate cost delivered field. One example is kg of CO2 per unit of measure.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricingDetail', 'currentTimeDate', false, 'dateTime', NULL, 'Current time as determined by a PAN device.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricingDetail', 'generationPrice', true, 'Money', NULL, 'Price of the commodity measured in base unit of currency per ''unitOfMeasure''.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricingDetail', 'generationPriceRatio', false, 'float', NULL, 'Ratio of ''generationPrice'' to the "normal" price chosen by the commodity provider.', 'schema/cim/IEC_CIM.ttl'),
  ('PanPricingDetail', 'price', true, 'Money', NULL, 'Price of the commodity measured in base unit of currency per ''unitOfMeasure''.', 'schema/cim/IEC_CIM.ttl'),
