  ('PendingCalculation', 'IntervalBlock', true, 'PendingCalculation', NULL, 'All blocks of interval reading values to which this pending conversion applies.Pending calculation to apply to interval reading values contained by this block (after which the resulting reading type is different than the original because it reflects the conversion result).', 'schema/cim/IEC_CIM.ttl'),
  ('PendingCalculation', 'multiplyBeforeAdd', false, 'boolean', NULL, 'Whether scalars should be applied before adding the ''offset''.', 'schema/cim/IEC_CIM.ttl'),
  ('PendingCalculation', 'offset', false, 'nonNegativeInteger', NULL, '(if applicable) Offset to be added as well as multiplication using scalars.', 'schema/cim/IEC_CIM.ttl'),
  ('PendingCalculation', 'scalarDenominator', false, 'nonNegativeInteger', NULL, '(if scalar is rational number) When ''IntervalReading.value'' is multiplied by ''scalarNumerator'' and divided by this value, it causes a unit of measure conversion to occur, resulting in the ''ReadingType.unit''.', 'schema/cim/IEC_CIM.ttl'),
  ('PendingCalculation', 'scalarFloat', false, 'float', NULL, '(if scalar is floating number) When multiplied with ''IntervalReading.value'', it causes a unit of measure conversion to occur, according to the ''ReadingType.unit''.', 'schema/cim/IEC_CIM.ttl'),
  ('PendingCalculation', 'scalarNumerator', false, 'nonNegativeInteger', NULL, '(if scalar is integer or rational number) When the scalar is a simple integer, and this attribute is presented alone and multiplied with ''IntervalReading.value'', it causes a unit of measure conversion to occur, resulting in the ''ReadingType.unit''. It is never used in conjunction with ''scalarFloat'', only with ''scalarDenominator''.', 'schema/cim/IEC_CIM.ttl'),
