  ('PerLengthPhaseImpedance', 'conductorCount', false, 'nonNegativeInteger', NULL, 'Number of phase, neutral, and other wires retained. Constrains the number of matrix elements and the phase codes that can be used with this matrix.', 'schema/cim/IEC_CIM.ttl'),
  ('PerLengthSequenceImpedance', 'b0ch', true, 'SusceptancePerLength', NULL, 'Zero sequence shunt (charging) susceptance, per unit of length.', 'schema/cim/IEC_CIM.ttl'),
  ('PerLengthSequenceImpedance', 'bch', true, 'SusceptancePerLength', NULL, 'Positive sequence shunt (charging) susceptance, per unit of length.', 'schema/cim/IEC_CIM.ttl'),
  ('PerLengthSequenceImpedance', 'g0ch', true, 'ConductancePerLength', NULL, 'Zero sequence shunt (charging) conductance, per unit of length.', 'schema/cim/IEC_CIM.ttl'),
