  ('PetersenCoil', 'mode', true, 'PetersenCoilModeKind', NULL, 'The mode of operation of the Petersen coil.', 'schema/cim/IEC_CIM.ttl'),
  ('PetersenCoil', 'nominalU', true, 'Voltage', NULL, 'The nominal voltage for which the coil is designed.', 'schema/cim/IEC_CIM.ttl'),
  ('PetersenCoil', 'offsetCurrent', true, 'CurrentFlow', NULL, 'The offset current that the Petersen coil controller is operating from the resonant point. This is normally a fixed amount for which the controller is configured and could be positive or negative. Typically 0 to 60 Amperes depending on voltage and resonance conditions.', 'schema/cim/IEC_CIM.ttl'),
  ('PetersenCoil', 'positionCurrent', true, 'CurrentFlow', NULL, 'The control current used to control the Petersen coil also known as the position current. Typically in the range of 20-200mA.', 'schema/cim/IEC_CIM.ttl'),
  ('PetersenCoil', 'xGroundMax', true, 'Reactance', NULL, 'The maximum reactance.', 'schema/cim/IEC_CIM.ttl'),
