  ('Priority', 'type', false, 'string', NULL, 'Type describing ''rank''; e.g., high, emergency, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('Procedure', 'CompatibleUnit', true, 'Procedure', NULL, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('Procedure', 'instruction', false, 'string', NULL, 'Textual description of this procedure.', 'schema/cim/IEC_CIM.ttl'),
  ('Procedure', 'kind', true, 'ProcedureKind', NULL, 'Kind of procedure.', 'schema/cim/IEC_CIM.ttl'),
  ('Procedure', 'sequenceNumber', false, 'string', NULL, 'Sequence number in a sequence of procedures being performed.', 'schema/cim/IEC_CIM.ttl'),
  ('ProcedureDataSet', 'Procedure', true, 'ProcedureDataSet', NULL, 'Procedure capturing this data set.All data sets captured by this procedure.', 'schema/cim/IEC_CIM.ttl'),
  ('ProcedureDataSet', 'UserAttribute', true, 'ProcedureDataSet', NULL, 'UserAttributes used to specify further properties of this procedure data set. Use ''name'' to specify what kind of property it is, and ''value.value'' attribute for the actual value.', 'schema/cim/IEC_CIM.ttl'),
  ('ProcedureDataSet', 'completedDateTime', false, 'dateTime', NULL, 'Date and time procedure was completed.', 'schema/cim/IEC_CIM.ttl'),
  ('Process', 'classificationType', false, 'string', NULL, 'The classification mechanism used to group a set of objects together within a business process. The grouping may be of a detailed or a summary nature.', 'schema/cim/IEC_CIM.ttl'),
