  ('SvInjection', 'qInjection', true, 'ReactivePower', NULL, 'The reactive power injected into the bus in addition to injections from equipment terminals. Positive sign means injection into the TopologicalNode (bus).', 'schema/cim/IEC_CIM.ttl'),
  ('SvPowerFlow', 'p', true, 'ActivePower', NULL, 'The active power flow. Load sign convention is used, i.e. positive sign means flow out from a TopologicalNode (bus) into the conducting equipment.', 'schema/cim/IEC_CIM.ttl'),
