  ('SwitchingPlan', 'purpose', false, 'string', NULL, 'Purpose of this plan, such as whether it is to move the state from normal to some abnormal condition, or to restore the normal state after an abnormal condition, or to perform some kind of optimisation such as correction of overload, voltage control, etc.', 'schema/cim/IEC_CIM.ttl'),
  ('SwitchingPlan', 'rank', false, 'nonNegativeInteger', NULL, 'Ranking in comparison to other switching plans.', 'schema/cim/IEC_CIM.ttl'),
