  ('TapChanger', 'neutralStep', false, 'nonNegativeInteger', NULL, 'The neutral tap step position for this winding. The attribute shall be equal or greater than lowStep and equal or less than highStep.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChanger', 'neutralU', true, 'Voltage', NULL, 'Voltage at which the winding operates at the neutral tap setting.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChanger', 'normalStep', false, 'nonNegativeInteger', NULL, 'The tap step position used in "normal" network operation for this winding. For a "Fixed" tap changer indicates the current physical tap setting. The attribute shall be equal or greater than lowStep and equal or less than highStep.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChanger', 'step', false, 'float', NULL, 'Tap changer position. Starting step for a steady state solution. Non integer values are allowed to support continuous tap variables. The reasons for continuous value are to support study cases where no discrete tap changers has yet been designed, a solutions where a narrow voltage band force the tap step to oscillate or accommodate for a continuous solution as input. The attribute shall be equal or greater than lowStep and equal or less than highStep.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChanger', 'subsequentDelay', true, 'Seconds', NULL, 'For an LTC, the delay for subsequent tap changer operation (second and later step changes)', 'schema/cim/IEC_CIM.ttl'),
  ('TapChangerControl', 'TapChanger', true, 'TapChangerControl', NULL, 'The tap changers that participates in this regulating tap control scheme.The regulating control scheme in which this tap changer participates.', 'schema/cim/IEC_CIM.ttl'),
  ('TapChangerControl', 'limitVoltage', true, 'Voltage', NULL, 'Maximum allowed regulated voltage on the PT secondary, regardless of line drop compensation. Sometimes referred to as first-house protection.', 'schema/cim/IEC_CIM.ttl'),
