  ('TimePoint', 'TimeSchedule', true, 'TimePoint', NULL, 'Time schedule owning this time point.Sequence of time points belonging to this time schedule.', 'schema/cim/IEC_CIM.ttl'),
  ('TimePoint', 'dateTime', false, 'dateTime', NULL, 'Absolute date and time for this time point. For calendar-based time point, it is typically manually entered, while for interval-based or sequence-based time point it is derived.', 'schema/cim/IEC_CIM.ttl'),
  ('TimePoint', 'relativeTimeInterval', true, 'Seconds', NULL, '(if interval-based) A point in time relative to scheduled start time in ''TimeSchedule.scheduleInterval.start''.', 'schema/cim/IEC_CIM.ttl'),
  ('TimePoint', 'sequenceNumber', false, 'nonNegativeInteger', NULL, '(if sequence-based) Relative sequence number for this time point.', 'schema/cim/IEC_CIM.ttl'),
