  ('TransformerCoreAdmittance', 'TransformerEndInfo', true, 'TransformerCoreAdmittance', NULL, 'Transformer end datasheet used to calculate this core admittance.Core admittance calculated from this transformer end datasheet, representing magnetising current and core losses. The full values of the transformer should be supplied for one transformer end info only.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerCoreAdmittance', 'b', true, 'Susceptance', NULL, 'Magnetizing branch susceptance (B mag). The value can be positive or negative.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerCoreAdmittance', 'b0', true, 'Susceptance', NULL, 'Zero sequence magnetizing branch susceptance.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerCoreAdmittance', 'g', true, 'Conductance', NULL, 'Magnetizing branch conductance (G mag).', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerCoreAdmittance', 'g0', true, 'Conductance', NULL, 'Zero sequence magnetizing branch conductance.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'TransformerCoreAdmittance', true, 'TransformerEnd', NULL, 'Core admittance of this transformer end, representing magnetising current and core losses. The full values of the transformer should be supplied for one transformer end only.All transformer ends having this core admittance.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'TransformerMeshImpedance', true, 'TransformerEnd', NULL, 'All mesh impedances between this ''from'' and other ''to'' transformer ends.All transformer ends this mesh impedance is connected to.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'WindingInsulation', true, 'TransformerEnd', NULL, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'bmagSat', true, 'PerCent', NULL, 'Core shunt magnetizing susceptance in the saturation region.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'endNumber', false, 'nonNegativeInteger', NULL, 'Number for this transformer end, corresponding to the end''s order in the power transformer vector group or phase angle clock number. Highest voltage winding should be 1. Each end within a power transformer should have a unique subsequent end number. Note the transformer end number need not match the terminal sequence number.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'grounded', false, 'boolean', NULL, '(for Yn and Zn connections) True if the neutral is solidly grounded.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'magBaseU', true, 'Voltage', NULL, 'The reference voltage at which the magnetizing saturation measurements were made', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'magSatFlux', true, 'PerCent', NULL, 'Core magnetizing saturation curve knee flux level.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'rground', true, 'Resistance', NULL, '(for Yn and Zn connections) Resistance part of neutral impedance where ''grounded'' is true.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEnd', 'xground', true, 'Reactance', NULL, '(for Yn and Zn connections) Reactive part of neutral impedance where ''grounded'' is true.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'NoLoadTest', true, 'TransformerEndInfo', NULL, 'All no-load test measurements in which this transformer end was energised.Transformer end that current is applied to in this no-load test.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'OpenCircuitTest', true, 'TransformerEndInfo', NULL, 'All open-circuit test measurements in which this transformer end was excited.Transformer end that current is applied to in this open-circuit test.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'ShortCircuitTest', true, 'TransformerEndInfo', NULL, 'All short-circuit test measurements in which this transformer end was energised.Transformer end that voltage is applied to in this short-circuit test. The test voltage is chosen to induce rated current in the energised end.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'TransformerTankInfo', true, 'TransformerEndInfo', NULL, 'Transformer tank data that this end description is part of.Data for all the ends described by this transformer tank data.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'connectionKind', true, 'WindingConnection', NULL, 'Kind of connection.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'emergencyS', true, 'ApparentPower', NULL, 'Apparent power that the winding can carry under emergency conditions (also called long-term emergency power).', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'endNumber', false, 'nonNegativeInteger', NULL, 'Number for this transformer end, corresponding to the end''s order in the PowerTransformer.vectorGroup attribute. Highest voltage winding should be 1.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'insulationU', true, 'Voltage', NULL, 'Basic insulation level voltage rating.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'phaseAngleClock', false, 'nonNegativeInteger', NULL, 'Winding phase angle where 360 degrees are represented with clock hours, so the valid values are {0, ..., 11}. For example, to express the second winding in code ''Dyn11'', set attributes as follows: ''endNumber''=2, ''connectionKind'' = Yn and ''phaseAngleClock'' = 11.', 'schema/cim/IEC_CIM.ttl');
INSERT INTO metadata.cim_ref_attributes (class_name, name, is_association, range, multiplicity, description, source) VALUES
  ('TransformerEndInfo', 'r', true, 'Resistance', NULL, 'DC resistance.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'ratedS', true, 'ApparentPower', NULL, 'Normal apparent power rating.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'ratedU', true, 'Voltage', NULL, 'Rated voltage: phase-phase for three-phase windings, and either phase-phase or phase-neutral for single-phase windings.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerEndInfo', 'shortTermS', true, 'ApparentPower', NULL, 'Apparent power that this winding can carry for a short period of time (in emergency).', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerMeshImpedance', 'TransformerEndInfo', true, 'TransformerMeshImpedance', NULL, '''from'' transformer end datasheet this mesh impedance is calculated from. It determines the voltage reference.All mesh impedances between this ''to'' and other ''from'' transformer ends.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerMeshImpedance', 'r', true, 'Resistance', NULL, 'Resistance between the ''from'' and the ''to'' end, seen from the ''from'' end.', 'schema/cim/IEC_CIM.ttl'),
