  ('TransformerMeshImpedance', 'x', true, 'Reactance', NULL, 'Reactance between the ''from'' and the ''to'' end, seen from the ''from'' end.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerMeshImpedance', 'x0', true, 'Reactance', NULL, 'Zero-sequence reactance between the ''from'' and the ''to'' end, seen from the ''from'' end.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'BushingInsulationPF', true, 'TransformerObservation', NULL, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'ProcedureDataSet', true, 'TransformerObservation', NULL, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'Reconditioning', true, 'TransformerObservation', NULL, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'bushingTemp', true, 'Temperature', NULL, 'Bushing temperature.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'dga', false, 'string', NULL, 'Dissolved Gas Analysis. Typical values are: Acceptable, Overheating, Corona, Sparking, Arcing.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'freqResp', false, 'string', NULL, 'Frequency Response Analysis. Typical values are: acceptable, slight movement, significant movement, failed, near failure. A graphic of the response diagram, which is a type of document, may be associated with this analysis through the recursive document relationship of the ProcedureDataSet.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'furfuralDP', false, 'string', NULL, 'Overall measure of furfural in oil and mechanical strength of paper. DP, the degree of polymerization, is the strength of the paper. Furfural is a measure of furfural compounds, often expressed in parts per million.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'hotSpotTemp', true, 'Temperature', NULL, 'Hotspot oil temperature.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'oilColor', false, 'string', NULL, 'Oil Quality Analysis-Color.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'oilDielectricStrength', true, 'Voltage', NULL, 'Oil Quality Analysis-Dielectric Strength.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'oilIFT', false, 'string', NULL, 'Oil Quality Analysis- inter facial tension (IFT) - number-Dynes/CM.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'oilLevel', false, 'string', NULL, 'The level of oil in the transformer.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'oilNeutralizationNumber', false, 'string', NULL, 'Oil Quality Analysis-Neutralization Number - Number - Mg KOH.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'pumpVibration', false, 'string', NULL, 'Pump vibration, with typical values being: nominal, high.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'status', true, 'Status', NULL, NULL, 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'topOilTemp', true, 'Temperature', NULL, 'Top oil temperature.', 'schema/cim/IEC_CIM.ttl'),
  ('TransformerObservation', 'waterContent', false, 'string', NULL, 'Water Content expressed in parts per million.', 'schema/cim/IEC_CIM.ttl'),
